+        } else if (ch == 34) { // '"'
+          inString = false;
+        }
+        continue;
+      }
+
+      if (ch == 34) { // '"'
+        inString = true;
+        continue;
+      }
+
+      if (ch == 91) { // '['
+        depth++;
+      } else if (ch == 93) { // ']'
+        depth--;
+        if (depth == 0) {
+          return input.substring(start, i + 1);
+        }
+      }
+    }
+
+    return null;
+  }
+
+  bool _parseBool(dynamic v) {
+    if (v == null) return false;
